// Validate, normalise and classify an inbound lead.
// Throws -> the Error Workflow (WF-D) fires. Never silently drops a lead.
const cfg = $vars ?? {};
const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

// 1. Honeypot. A bot filling the hidden field looks exactly like a real post.
if (body._gotcha) { return [{ json: { reject: true, code: 400, reason: 'honeypot' } }]; }

// 2. Required fields.
const name = String(body.name ?? body.client_name ?? '').trim();
if (!name) { return [{ json: { reject: true, code: 400, reason: 'missing name' } }]; }

// 3. Normalise. email_norm / phone_norm are the partial-unique-index keys, so
//    normalisation IS the dedupe rule -- keep it boring and deterministic.
const emailRaw = String(body.email ?? '').trim().toLowerCase();
const email = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(emailRaw) ? emailRaw : null;

let phone = String(body.phone ?? '').replace(/[^\d+]/g, '');
if (phone.startsWith('0'))       phone = '+27' + phone.slice(1);   // ZA local -> E.164
else if (phone.startsWith('27')) phone = '+' + phone;
if (phone && !/^\+\d{8,15}$/.test(phone)) phone = null;
if (!phone) phone = null;

if (!email && !phone) {
  return [{ json: { reject: true, code: 400, reason: 'no contactable channel' } }];
}

// 4. Classify. Rules come from config, not hardcoded, so a new vertical is a
//    config edit rather than a workflow edit.
const timeline = String(body.timeline ?? '').toLowerCase();
const budget   = String(body.budget   ?? '').toLowerCase();
const topic    = String(body.topic    ?? '').toLowerCase();
const urgentTimelines = (cfg.urgent_timelines ?? 'asap,lt-1-month').split(',');
const urgentBudgets   = (cfg.urgent_budgets   ?? '100k-150k,150k-plus').split(',');
const urgent = urgentTimelines.includes(timeline) || urgentBudgets.includes(budget);

// 5. Quiet hours. An 02:00 SMS burns the lead; the 08:00 follow-up covers it.
//    ponytail: no SMS queue table until there is evidence one is needed.
const tz   = cfg.timezone ?? 'Africa/Johannesburg';
const hour = Number(new Intl.DateTimeFormat('en-GB',
  { timeZone: tz, hour: 'numeric', hour12: false }).format(new Date()));
const qs = Number(cfg.quiet_start ?? 20), qe = Number(cfg.quiet_end ?? 7);
const quiet = qs > qe ? (hour >= qs || hour < qe) : (hour >= qs && hour < qe);

// 6. Signature base. Signing a fixed string beats signing the raw body: no JSON
//    canonicalisation mismatch between Cloudflare Workers and n8n.
const ref  = String(body.submissionId ?? body.ref ?? '').trim();
const ts   = String(body.submittedAt ?? '').trim();
const skew = ts ? Math.abs(Date.now() - Date.parse(ts)) / 1000 : Infinity;
if (!ref || !ts)      return [{ json: { reject: true, code: 400, reason: 'missing ref/timestamp' } }];
if (!(skew < 300))    return [{ json: { reject: true, code: 401, reason: 'stale or unparseable timestamp' } }];

return [{ json: {
  reject: false,
  sigBase: `${ref}.${ts}.${email ?? phone}`,
  providedSig: String(body.signature ?? ''),
  lead: {
    email_norm: email, phone_norm: phone, name,
    service_type: String(body.service ?? body.topic ?? '').trim() || null,
    urgency: urgent ? 'urgent' : 'normal',
    consent_source: 'website_form',
  },
  submission: {
    ref, source: String(body.source ?? 'website'),
    utm_source: body.utm_source ?? null, utm_medium: body.utm_medium ?? null,
    utm_campaign: body.utm_campaign ?? null,
    entry_point: body.entryPoint ?? body.entry_point ?? null, topic: topic || null,
    raw: JSON.stringify(body),
  },
  quiet, urgent,
} }];
